import { Request, Response } from 'express';
import { {name}Service } from '../services/{name}.service';

export class {name}Controller {
  private {name}Service: {name}Service;

  constructor() {
    this.{name}Service = new {name}Service();
  }

  async getAll(req: Request, res: Response): Promise<void> {
    try {
      const items = await this.{name}Service.findAll();
      res.json(items);
    } catch (error) {
      res.status(500).json({ error: 'Error al obtener {name}s' });
    }
  }
}

services.content:
import { prisma } from '../../config/database';

export class {name}Service {
  async findAll() {
    return await prisma.{name}.findMany();
  }

  async findById(id: string) {
    return await prisma.{name}.findUnique({
      where: { id }
    });
  }

  async create(data: any) {
    return await prisma.{name}.create({
      data
    });
  }
}

